const MS_PER_DAY = 86_400_000;
const FRESH_DAYS = 14;
const ISO_DATE = /^(\d{4})-(\d{2})-(\d{2})$/;

/** Whole days since the ISO date roastedOn (e.g. "2026-10-12"), measured on the UTC calendar. */
export function daysSinceRoast(roastedOn: string, today: Date): number {
  const match = ISO_DATE.exec(roastedOn);
  if (!match) throw new RangeError(`invalid roast date: ${roastedOn}`);
  const roast = Date.UTC(Number(match[1]), Number(match[2]) - 1, Number(match[3]));
  const day = Date.UTC(today.getUTCFullYear(), today.getUTCMonth(), today.getUTCDate());
  return Math.round((day - roast) / MS_PER_DAY);
}

/** True for 14 days after roasting, inclusive. */
export function isFresh(roastedOn: string, today: Date): boolean {
  return daysSinceRoast(roastedOn, today) <= FRESH_DAYS;
}

import { test } from "node:test";
import assert from "node:assert/strict";
import { daysSinceRoast, isFresh } from "../src/freshness.ts";

test("day 0: roasted today", () => {
  const today = new Date("2026-10-12");
  assert.equal(daysSinceRoast("2026-10-12", today), 0);
  assert.equal(isFresh("2026-10-12", today), true);
});

test("day 14: still fresh (inclusive)", () => {
  const today = new Date("2026-10-26");
  assert.equal(daysSinceRoast("2026-10-12", today), 14);
  assert.equal(isFresh("2026-10-12", today), true);
});

test("day 15: no longer fresh", () => {
  const today = new Date("2026-10-27");
  assert.equal(daysSinceRoast("2026-10-12", today), 15);
  assert.equal(isFresh("2026-10-12", today), false);
});
